import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const root = process.cwd();
const fromRoot = (path) => pathToFileURL(join(root, path)).href;
const { ready } = await import(fromRoot('test/account-service-delivery/fixtures.mjs'));
const { query, read } = await import(fromRoot('test/account-service-inbound/oracle.mjs'));
const { decodeInboundPage } = await import(fromRoot('account-protocol/inboundTransport.ts'));
const { build } = await import(pathToFileURL(createRequire(join(root, 'package.json')).resolve('vite')).href);
const temp = await mkdtemp(join(tmpdir(), 'done-r01-bundle-'));
try {
  await build({ configFile: false, logLevel: 'silent', build: { outDir: temp, emptyOutDir: false, minify: false,
    lib: { entry: join(root, 'src/crdt/accountInbound.ts'), formats: ['es'], fileName: () => 'inbound.mjs' } } });
  const { verifyInboundPage, InboundError } = await import(pathToFileURL(join(temp, 'inbound.mjs')).href);
  for (const bytes of [16384, 614400, 4 * 1024 * 1024]) {
    const cleanups = [];
    try {
      const x = await ready({ after: (fn) => cleanups.push(fn) });
      const result = await x.call(x.make(1, 'x'.repeat(bytes)));
      const output = { updateBytes: bytes, serviceKind: result.kind, serviceReason: result.reason ?? null };
      if (result.kind === 'decision') {
        const q = query(x), page = await read(x, q);
        assert.equal(page.kind, 'decision');
        const wireBytes = decodeInboundPage(page.bytes).entries[0].envelope.length;
        Object.assign(output, { readKind: page.kind, envelopeBytes: wireBytes, exceedsReceiverWireLimit: wireBytes > 512 * 1024 });
        if (bytes === 614400) {
          const publicKey = x.s.publicKey.export({ format: 'der', type: 'spki' }).subarray(-32).toString('hex');
          const context = {
            baseline: { kind: 'promotion-genesis', id: '00'.repeat(32) },
            service: { id: x.authority.pin.serviceId, origin: x.authority.pin.origin },
            authority: { workspace: x.workspace, lineage: x.offer.epoch.lineageId,
              head: x.offer.head, tip: 1, acceptanceKey: x.offer.epoch.acceptancePublicKey },
            creatingCredential: x.credential,
            reader: { id: x.credential, publicKey, active: true },
            publisher: { id: x.credential, publicKey, active: true,
              principal: x.request.candidate.principalId, system: true },
            generation: 1, generationKey: new Uint8Array(32),
            prefix: { position: 0, link: '00'.repeat(32), observedThrough: 0 },
          };
          await assert.rejects(verifyInboundPage(context, q, page.bytes, { assertCurrent() {} }),
            (e) => { output.receiverError = e.name; output.receiverReason = e.reason;
              return e instanceof InboundError && e.reason === 'size'; });
        }
      }
      console.log(JSON.stringify(output));
    } finally { for (const cleanup of cleanups.reverse()) await cleanup(); }
  }
} finally { await rm(temp, { recursive: true, force: true }); }
